#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")"
source scripts/source_mujoco_setup.sh "${1:-box_75}"
SIM="${HOLOSOMA_MJ_SIMULATOR:-mujoco-split-debug}"
export TRAINING_HEADLESS="${TRAINING_HEADLESS:-False}"
[[ -f "$HOLOSOMA_MJ_MOTION" && -f "$HOLOSOMA_MJ_OBJECT_URDF" && -f "${HOLOSOMA_MJ_OBJECT_URDF%.urdf}.obj" ]] || { echo "missing data_demo files for $HOLOSOMA_MJ_CLIP" >&2; exit 1; }
python -u src/holosoma/holosoma/run_sim.py simulator:"$SIM" robot:g1-29dof-w-object-mujoco terrain:terrain-locomotion-plane perception:"$PERCEPTION_PRESET" --training.headless "$TRAINING_HEADLESS" --device "$SIM_DEVICE" --motion-init.enabled=True --motion-init.motion-file "$HOLOSOMA_MJ_MOTION" --motion-init.mode "$SIM_MOTION_INIT_MODE" --motion-init.object-name object --simulator.config.debug-viz "$SIM_DEBUG_VIZ" --simulator.config.contact-force-viz "$SIM_CONTACT_FORCE_VIZ" --simulator.config.sim.fps "$SIM_FPS" --simulator.config.sim.control-decimation "$SIM_CONTROL_DECIMATION" --simulator.config.bridge.clock-port "$SIM_CLOCK_PORT" --simulator.config.bridge.sim-state-port "$SIM_STATE_PORT" --simulator.config.bridge.perception-obs-port "$PERCEPTION_OBS_PORT" --simulator.config.bridge.control-port "$SIM_CONTROL_PORT" --simulator.config.bridge.perception-obs-shm-name "$PERCEPTION_OBS_SHM_NAME" --perception.camera-source "$PERCEPTION_CAMERA_SOURCE" --perception.object-geometry-mode "$PERCEPTION_OBJECT_GEOMETRY_MODE" --perception.camera-warp-edge-noise "$PERCEPTION_CAMERA_WARP_EDGE_NOISE" --perception.camera-warp-enable-holes "$PERCEPTION_CAMERA_WARP_ENABLE_HOLES" --perception.camera-apply-sensor-noise "$PERCEPTION_CAMERA_APPLY_SENSOR_NOISE"
